import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type TrafficLightAnimationProps = Record<string, any>;

const TrafficLightAnimation: React.FC<TrafficLightAnimationProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 8,
  strokeColor = "#1A1A1A",
  redColor = "#EF233C",
  yellowColor = "#FFD166",
  greenColor = "#06D6A0",
  dimOpacity = 0.15,
  lineWidth = 6,
}) => {
  {/* Load Google Fonts (Included for strict compliance, even if unused in this purely graphical component) */ }
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timings (Frames)
  const drawDuration = 60;
  const redOnFrame = 45;
  const redOffFrame = 120;
  const greenOnFrame = 130;

  // 1. Draw In Animation
  const drawProgress = spring({
    frame,
    fps,
    config: { damping: 100, mass: 3 }, // Slow, deliberate draw
    durationInFrames: drawDuration,
  });
  
  // Use a very large dasharray to cover all path lengths
  const pathLength = 4000;
  const strokeDashoffset = interpolate(drawProgress, [0, 1], [pathLength, 0]);

  // 2. Light Sequence Animations
  const redOnSpring = spring({ frame: frame - redOnFrame, fps, config: { damping: 12 } });
  const redOffSpring = spring({ frame: frame - redOffFrame, fps, config: { damping: 12 } });
  const greenOnSpring = spring({ frame: frame - greenOnFrame, fps, config: { damping: 12 } });

  // Calculate active values (0 to 1) for each light
  const redActive = Math.max(0, redOnSpring - redOffSpring);
  const yellowActive = 0; // Remains dim in this specific "turning green" sequence
  const greenActive = greenOnSpring;

  // Messy, hand-drawn styled SVG paths
  const paths = [
    // Outer shell 1
    "M 340 380 C 370 330, 680 340, 720 380 C 760 420, 740 1400, 720 1500 C 700 1600, 360 1580, 330 1500 C 300 1420, 310 420, 340 380 Z",
    // Outer shell 2 (inner offset for sketched look)
    "M 360 400 C 400 370, 650 370, 690 400 C 720 450, 710 1380, 690 1480 C 650 1520, 390 1540, 360 1480 C 330 1420, 340 450, 360 400 Z",
    // Left entering wire
    "M -100 950 C 50 940, 200 970, 345 960",
    // Right exiting wire
    "M 705 980 C 850 960, 1000 1000, 1180 950",
    // Red inner loop
    "M 520 360 C 630 340, 680 430, 670 520 C 660 610, 600 680, 510 660 C 420 640, 360 580, 380 490 C 400 400, 460 370, 520 360 Z",
    // Yellow inner loop
    "M 540 810 C 650 820, 700 910, 680 1000 C 660 1090, 610 1140, 520 1120 C 430 1100, 370 1040, 390 950 C 410 860, 470 800, 540 810 Z",
    // Green inner loop
    "M 510 1280 C 620 1260, 690 1350, 680 1440 C 670 1530, 600 1600, 510 1580 C 420 1560, 360 1490, 380 1400 C 400 1310, 450 1290, 510 1280 Z"
  ];

  const renderLight = (cx: number, cy: number, color: string, activeValue: number) => {
    // Interpolate using strictly ascending input ranges as required
    const scale = interpolate(activeValue, [0, 1], [0.9, 1]);
    const opacity = interpolate(activeValue, [0, 1], [dimOpacity, 1]);
    const glow = activeValue > 0.5 ? `drop-shadow(0px 0px 30px ${color}80)` : 'none';

    return (
      <circle
        cx={cx}
        cy={cy}
        r="140"
        fill={color}
        style={{
          opacity,
          transform: `scale(${scale})`,
          transformOrigin: `${cx}px ${cy}px`,
          filter: glow,
          transition: "none",
        }}
      />
    );
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", transition: "none" }}>
      <svg
        viewBox="0 0 1080 1920"
        style={{
          width: "100%",
          height: "100%",
          display: "block",
          transition: "none",
        }}
      >
        {/* Lights Group (rendered behind strokes) */}
        <g style={{ transition: "none" }}>
          {renderLight(525, 515, redColor, redActive)}
          {renderLight(535, 965, yellowColor, yellowActive)}
          {renderLight(525, 1435, greenColor, greenActive)}
        </g>

        {/* Line Art Strokes Group */}
        <g
          fill="none"
          stroke={strokeColor}
          strokeWidth={lineWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeDasharray={pathLength}
          strokeDashoffset={strokeDashoffset}
          style={{ transition: "none" }}
        >
          {paths.map((d, i) => (
            <path key={i} d={d} style={{ transition: "none" }} />
          ))}
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default TrafficLightAnimation;